import{_ as a,C as n,o as s,c as r,E as o,a2 as i}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse(`{"title":"Tokens Aren't a Bill: Agent Cost Screens Must Separate Usage, Included Value, and Amount Due","description":"","frontmatter":{"title":"Tokens Aren't a Bill: Agent Cost Screens Must Separate Usage, Included Value, and Amount Due","date":"2026-08-17","column":"industry-architecture","category":"daily","article_type":"practical-explainer","edition":"research-center","research_question":"How should an AI agent product present usage, included entitlements, and billed cost so that users can make real spending decisions?","summary":"A token count measures consumption. It cannot reveal what a plan absorbed, what is only estimated as billable, or what has reached an invoice. Agent cost screens need separate usage, entitlement, and billing ledgers.","sources":["research/manual-runs/2026-08-17-high-quality-article-pipeline/10-forum-demand-discovery-2026-08-18.md","research/manual-runs/2026-08-17-high-quality-article-pipeline/11-two-topic-deep-reading-and-fact-matrix.md","research/manual-runs/2026-08-17-high-quality-article-pipeline/12-two-topic-article-briefs.md"],"item_id":"MANUAL-20260817-COST","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-17-token-is-not-a-bill-cover.webp","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/industry/2026-08-17-token-is-not-a-bill.md","filePath":"en/industry/2026-08-17-token-is-not-a-bill.md","lastUpdated":1787026891000}`),l={name:"en/industry/2026-08-17-token-is-not-a-bill.md"};function c(d,e,u,p,h,m){const t=n("ArticleCover");return s(),r("div",null,[o(t,{image:"/assets/covers/daily-2026-08-17-token-is-not-a-bill-cover.webp",kicker:"Industry Architecture · Research Article",title:"Tokens Aren't a Bill: Agent Cost Screens Must Separate Usage, Included Value, and Amount Due",summary:"A token count measures consumption. It cannot reveal what a plan absorbed, what is only estimated as billable, or what has reached an invoice. Agent cost screens need separate usage, entitlement, and billing ledgers.",version:"MANUAL-20260817-COST",status:"Independent Editorial PASS · 2026-08-18",languageHref:"/zh/industry/2026-08-17-token-is-not-a-bill",languageLabel:"中文"}),e[0]||(e[0]=i(`<h1 id="tokens-aren-t-a-bill-agent-cost-screens-must-separate-usage-included-value-and-amount-due" tabindex="-1">Tokens Aren&#39;t a Bill: Agent Cost Screens Must Separate Usage, Included Value, and Amount Due <a class="header-anchor" href="#tokens-aren-t-a-bill-agent-cost-screens-must-separate-usage-included-value-and-amount-due" aria-label="Permalink to &quot;Tokens Aren&#39;t a Bill: Agent Cost Screens Must Separate Usage, Included Value, and Amount Due&quot;">​</a></h1><p>Imagine a product review in which the usage page shows <strong>2.3 million tokens</strong>. Engineering calls the number accurate. Finance asks what will be owed. The team administrator asks how much the subscription covered. The developer asks which model, task, or cache miss caused the spike.</p><p>The number can be accurate and still fail every decision in the room.</p><p>This is not a theoretical UX edge case. In July 2026, several users in one <a href="https://forum.cursor.com/t/usage-page-to-token-amount-what/167153" target="_blank" rel="noreferrer">Cursor Forum discussion</a> objected when a usage view replaced dollar figures with token counts. They wanted daily, per-user, and per-model cost visibility. Cursor staff explained the counterproblem: a list-price dollar equivalent for included usage could exceed the subscription price and be mistaken for a charge; the available detail also varied by plan and admin access. <a href="https://forum.cursor.com/t/usage-page-to-token-amount-what/167153" target="_blank" rel="noreferrer">[1]</a></p><p>The product lesson is not that dollars beat tokens. It is that one field is being asked to represent three different data objects: a <strong>meter</strong>, an <strong>entitlement ledger</strong>, and a <strong>billing ledger</strong>.</p><h2 id="the-meter-is-for-engineering-truth" tabindex="-1">The meter is for engineering truth <a class="header-anchor" href="#the-meter-is-for-engineering-truth" aria-label="Permalink to &quot;The meter is for engineering truth&quot;">​</a></h2><p>Input, output, and cache tokens describe resource consumption. They help an engineer find prompt growth, long trajectories, cache misses, and model-level efficiency problems. Removing them would destroy useful operational evidence.</p><p>But consumption does not determine payment on its own. The FinOps Foundation&#39;s <a href="https://focus.finops.org/focus-specification/v1-3/" target="_blank" rel="noreferrer">FOCUS v1.3 specification</a> separates <code>Consumed Quantity</code> from <code>Pricing Quantity</code>, then defines Billed, Contracted, Effective, and List Cost as distinct concepts. <a href="https://focus.finops.org/focus-columns/" target="_blank" rel="noreferrer">[2]</a> The separation exists because a measured unit can pass through pricing units, contract terms, discounts, and billing adjustments before it becomes money owed.</p><p>An agent meter therefore needs enough provenance to answer four technical questions: what unit was counted, over what scope, under which model or router mode, and at what observation time. It should never label a raw token total as “amount paid.”</p><h2 id="the-entitlement-ledger-explains-the-gap" tabindex="-1">The entitlement ledger explains the gap <a class="header-anchor" href="#the-entitlement-ledger-explains-the-gap" aria-label="Permalink to &quot;The entitlement ledger explains the gap&quot;">​</a></h2><p>Most confusion sits between usage and payment. A subscription may include capacity; a team may pool it; a contract may discount it; only the excess may become on-demand spend. Two identical agent runs can therefore create different charges.</p><p>Cursor&#39;s current <a href="https://cursor.com/en-US/business/teams" target="_blank" rel="noreferrer">Teams page</a> distinguishes included usage from on-demand usage. For users with team-admin access, the current <a href="https://cursor.com/docs/account/teams/admin-api" target="_blank" rel="noreferrer">Admin API</a> exposes daily subscription-included and usage-based requests, member spend, and granular usage events. Those events can identify the model, token breakdown, and usage kind. The distinction inside the cost fields matters: <code>totalCents</code> represents model cost, while <code>chargedCents</code> is the event-level charge used to reconcile against spend totals. <a href="https://cursor.com/docs/account/teams/admin-api" target="_blank" rel="noreferrer">[3]</a></p><p>GitHub&#39;s official billing-reporting guidance provides an independent version of the same pattern. It uses <code>quantity</code> to describe consumption, <code>netAmount</code> for billed cost, and <code>discountAmount</code> for the <strong>monetary value</strong> covered by an allowance or discount. <a href="https://docs.github.com/en/billing/tutorials/automate-usage-reporting" target="_blank" rel="noreferrer">[4]</a> An entitlement balance still needs its own unit—tokens, requests, credits, or contract currency—rather than being inferred from that discount amount.</p><p>The ledger should make five things explicit: opening allowance, consumed allowance, remaining allowance, allowance unit, and included or discounted value. Without it, a dollars-only page can make included value resemble a new charge, while a tokens-only page conceals the approach of an overage.</p><h2 id="the-billing-ledger-needs-states-not-one-cost-column" tabindex="-1">The billing ledger needs states, not one “cost” column <a class="header-anchor" href="#the-billing-ledger-needs-states-not-one-cost-column" aria-label="Permalink to &quot;The billing ledger needs states, not one “cost” column&quot;">​</a></h2><p>Even after usage and entitlements are known, money moves through stages:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>estimated billable</span></span>
<span class="line"><span>→ posted or billed</span></span>
<span class="line"><span>→ invoiced amount due</span></span>
<span class="line"><span>→ adjusted or refunded</span></span></code></pre></div><p>A live estimate is not yet an invoice. A posted charge may still be corrected. Only an invoiced amount—or a vendor-defined equivalent final settlement state—should be presented as the amount finally due. Each state needs a currency, payer or billing entity, billing period, and update time.</p><p>OpenAI&#39;s organization APIs reinforce the object boundary: usage resources return such dimensions as tokens, requests, projects, and users, while a separate costs resource returns a monetary <code>amount</code> with <code>currency</code> and <code>value</code>. <a href="https://developers.openai.com/api/reference/resources/admin/subresources/organization/subresources/usage" target="_blank" rel="noreferrer">[5]</a> That separation does <strong>not</strong> establish that every live API cost is already a final invoice figure.</p><p>Routing adds another moving part. Cursor documents Router for Teams and Enterprise as a changing model pool in which the user cannot select every routed model. Cost mode uses bundled Auto pricing; Balance and Intelligence are billed at the routed model&#39;s rate. <strong>According to Cursor&#39;s current estimate</strong>, those two modes cost about twice as much as Cost on average and may be roughly two to four times as expensive depending on the mode. <a href="https://cursor.com/docs/cursor-router" target="_blank" rel="noreferrer">[6]</a> This is a vendor estimate about cost, not an independently measured multiplier for token usage.</p><p>That is why multiplying 2.3 million tokens by one public rate can produce a precise-looking but wrong answer. The actual route, entitlement, contract terms, and settlement state all intervene.</p><h2 id="a-screen-should-survive-six-user-questions" tabindex="-1">A screen should survive six user questions <a class="header-anchor" href="#a-screen-should-survive-six-user-questions" aria-label="Permalink to &quot;A screen should survive six user questions&quot;">​</a></h2><p>A product team can review its cost experience without inventing a new FinOps framework. Put a real usage record on screen and ask:</p><ol><li>Can the user see whether the number represents input, output, cache, requests, or converted credits?</li><li>Can the user see what the plan or contract absorbed and in which unit?</li><li>Is estimated billable money visually distinct from a posted or billed charge?</li><li>Does the interface reserve “amount due” for an invoice or equivalent final state?</li><li>Can a team trace the number to a user, project, model, and agent task?</li><li>Does a historical event retain the pricing and routing version that applied at the time?</li></ol><p>If answering requires a CSV export plus a private conversion script, the product has exposed records but has not delivered cost control.</p><h2 id="the-minimum-event-contract" tabindex="-1">The minimum event contract <a class="header-anchor" href="#the-minimum-event-contract" aria-label="Permalink to &quot;The minimum event contract&quot;">​</a></h2><p>The sources above do not jointly prescribe one cross-vendor schema. The following is a Research Center synthesis designed to preserve the boundaries they reveal:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>usage: input / output / cache quantity + unit</span></span>
<span class="line"><span>entitlement: unit + included / discounted quantity + included value + balance</span></span>
<span class="line"><span>billing: estimated billable + posted/billed + invoiced due + adjusted/refunded</span></span>
<span class="line"><span>money: currency + payer/payee + settlement status + updated time</span></span>
<span class="line"><span>pricing: model + router mode + pricing version</span></span>
<span class="line"><span>scope: user + project + work order + request/run id</span></span>
<span class="line"><span>time: usage time + charge period + billing period</span></span></code></pre></div><p>The contract is valuable because it lets an auditor reconstruct three different answers: what the agent consumed, what commercial terms absorbed, and how far a monetary amount has progressed toward an invoice.</p><h2 id="where-this-model-stops" tabindex="-1">Where this model stops <a class="header-anchor" href="#where-this-model-stops" aria-label="Permalink to &quot;Where this model stops&quot;">​</a></h2><p>No live cost screen can promise exact invoice parity before settlement. Refunds, corrections, commitment amortization, negotiated discounts, taxes, and currency conversion may change the result. The responsible design is to display state and freshness, not more decimal places.</p><p>Tokens should remain prominent for diagnosis. Monetary estimates should remain prominent for spending decisions. Entitlements should explain the gap between them. The failure is not choosing the wrong one of those three numbers; it is forcing one number to impersonate all three.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><ol><li><a href="https://forum.cursor.com/t/usage-page-to-token-amount-what/167153" target="_blank" rel="noreferrer">Cursor Forum: Usage Page $$ to Token Amount? WHAT?</a></li><li><a href="https://focus.finops.org/focus-specification/v1-3/" target="_blank" rel="noreferrer">FinOps Open Cost and Usage Specification</a> and <a href="https://focus.finops.org/focus-columns/" target="_blank" rel="noreferrer">FOCUS Column Library</a></li><li><a href="https://cursor.com/docs/account/teams/admin-api" target="_blank" rel="noreferrer">Cursor Admin API</a> and <a href="https://cursor.com/en-US/business/teams" target="_blank" rel="noreferrer">Cursor Teams</a></li><li><a href="https://docs.github.com/en/billing/tutorials/automate-usage-reporting" target="_blank" rel="noreferrer">GitHub: Automating usage reporting with the REST API</a></li><li><a href="https://developers.openai.com/api/reference/resources/admin/subresources/organization/subresources/usage" target="_blank" rel="noreferrer">OpenAI Organization Usage / Costs API</a></li><li><a href="https://cursor.com/docs/cursor-router" target="_blank" rel="noreferrer">Cursor Router Docs</a></li></ol>`,34))])}const f=a(l,[["render",c]]);export{b as __pageData,f as default};
